paragraph.math:
$$\begin{array}{l}
  {{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}{\frac{f(x + h) - f(x)}{h} = \lim\limits_{h\rightarrow 0}\frac{{\lbrack{{({x + h})}^{3} - {({x + h})}}\rbrack} - {\lbrack{x^{3} - x}\rbrack}}{h}}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{x^{3} + 3x^{2}h + 3xh^{2} + h^{3} - x - h - x^{3} + x}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{3x^{2}h + 3xh^{2} + h^{3} - h}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}{({3x^{2} + 3xh + h^{2} - 1})} = 3x^{2} - 1}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{f(x + h) - f(x)}{h}} = {\lim\limits_{h\rightarrow 0}\frac{\sqrt{x + h} - \sqrt{x}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\left( {\frac{\sqrt{x + h} - \sqrt{x}}{h} \cdot \frac{\sqrt{x + h} + \sqrt{x}}{\sqrt{x + h} + \sqrt{x}}} \right)\qquad{({{Rationalize\ the\ numerator}.})}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}{\frac{{({x + h})} - x}{h({\sqrt{x + h} + \sqrt{x}})} = \lim\limits_{h\rightarrow 0}\frac{h}{h({\sqrt{x + h} + \sqrt{x}})}}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}{\frac{1}{\sqrt{x + h} + \sqrt{x}} = \frac{1}{\sqrt{x} + \sqrt{x}} = \frac{1}{2\sqrt{x}}}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{\left| x + h \middle| - \middle| x \right|}{h} = \lim\limits_{h\rightarrow 0}\frac{- \left( {x + h} \right) - \left( {- x} \right)}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{- h}{h} = \lim\limits_{h\rightarrow 0}\left( {- 1} \right) = - 1}}
  \end{array}$$
